// No preconditions documented; just call and ignore the return for coverage
int maxc = vips_max_coord_get();
(void) maxc; // suppress unused warning

// Initialize libvips with a fuzzed argv0 (NUL-terminated via c_str()).
// Enforce single successful initialization per process using a global flag.
if (FUZZ_GET_ATTR_INT_GLOBAL("vips_inited")) { FUZZ_BAIL(); }
std::string argv0 = FUZZ_PARAM_STR();
int rc = vips_init(argv0.c_str());
if (rc != 0) { FUZZ_BAIL(); }
// Mark library as initialized for downstream stubs
FUZZ_SET_ATTR_INT_GLOBAL("vips_inited", 1);

// Must be called after successful vips_init()
if (!FUZZ_GET_ATTR_INT_GLOBAL("vips_inited")) { FUZZ_BAIL(); }
const char *p = vips_get_argv0();
(void) p;

// Must be called after successful vips_init()
if (!FUZZ_GET_ATTR_INT_GLOBAL("vips_inited")) { FUZZ_BAIL(); }
const char *p = vips_get_prgname();
(void) p;

// Only shutdown if we previously initialized
if (!FUZZ_GET_ATTR_INT_GLOBAL("vips_inited")) { FUZZ_BAIL(); }
vips_shutdown();
// After shutdown, mark as uninitialized
FUZZ_SET_ATTR_INT_GLOBAL("vips_inited", 0);

// Thread teardown should only happen after initialization to avoid undefined behavior
if (!FUZZ_GET_ATTR_INT_GLOBAL("vips_inited")) { FUZZ_BAIL(); }
vips_thread_shutdown();

// Accept any gboolean (0 or 1)
gboolean leak = (gboolean)(*FUZZ_PARAM(unsigned int) % 2);
vips_leak_set(leak);

// Accept any gboolean (0 or 1)
gboolean state = (gboolean)(*FUZZ_PARAM(unsigned int) % 2);
vips_block_untrusted_set(state);

// No preconditions documented; call and ignore result
const char *s = vips_version_string();
(void) s;

// Fuzz a small range of flags to exercise multiple branches if present
int flag = (int)(*FUZZ_PARAM(unsigned int) % 8); // flags 0..7
int v = vips_version(flag);
(void) v;

// Provide non-null NUL-terminated strings for argv0 and env_name
std::string argv0 = FUZZ_PARAM_STR();
std::string env = FUZZ_PARAM_STR();
const char *p = vips_guess_prefix(argv0.c_str(), env.c_str());
(void) p;

// Provide non-null NUL-terminated strings for argv0 and env_name
std::string argv0 = FUZZ_PARAM_STR();
std::string env = FUZZ_PARAM_STR();
const char *p = vips_guess_libdir(argv0.c_str(), env.c_str());
(void) p;
